-- Nuzlocke 2.8.02
-- Full release, strict child of exact packaged 2.7.106. Repairs the Gen2 Pack
-- party-consumable commit seam at the authoritative live party slot and retunes
-- five-stage held UP/DOWN navigation. Protected TOOLS profile semantics, World
-- Building T3 default, Random Starter and tracker/compat behavior remain intact.
-- Historical version lineage is maintained in CHANGELOG.md and docs/DOCUMENTATION_CHANGELOG.md.
--
-- Lineage:
-- * beta.26 is promoted directly from the runtime-tested 26B10 development revision
-- * 26B10 descended forward from the published 25D4-RBY2 startup/menu hotfix
-- * older branches are reference material only; missing behavior is ported surgically after comparison
-- * schema 4 and the established persisted rule surface remain preserved
-- * Gen 2 adapters remain isolated behind explicit generation checks
--
-- BETA.29 PROTECTED RUNTIME / FOLLOW-UP NOTES
-- * Runtime PASS: Gold NEW GAME reaches Nuzlocke Setup; collapsible Setup
--   sections function.
-- * Runtime PASS: Yellow existing-save numeric/config selection uses A or
--   Left/Right instead of consuming Up/Down navigation; collapsible sections
--   function and broad rule behavior was reported healthy.
-- * UI follow-up: R/B/Y retains its protected screen presentation. Gold/Silver
--   render Nuz Rules/Setup, Encounter Tracker, Catch Info, Forgiveness, and
--   Nuz Status with native Gen 2 Chrome; exact-edition runtime presentation is TEST REQUIRED.
-- * beta.29.2.0 separates missed/lost encounters from Pokemon deaths while
--   conservatively migrating legacy death history that used LOST bookkeeping.
return function(mod)
  local unpackValues = table.unpack or unpack
  assert(type(unpackValues) == "function", "Nuzlocke requires Lua unpack support")
  -- 2.6.29: forward-declare cross-scope runtime helpers before any callback
  -- captures them. Modular compiler-budget scopes must never fall back to _ENV.
  local currentGame
  local defaultRuleValue
  local pendingNewGameRules
  local gscProgress
  local currentGymProgressCount

  mod.exports.__beta26 = {
      build = "2.8.02",
      -- Version titles are numeric-only from 2.5.41 onward. The updater-safe
      -- behavior previously obtained with +DEV is preserved by simply using
      -- the canonical numeric release/build identity.
      manifestVersion = "2.8.02",
      setupProfileScope = "gen1",
      parentVersion = "2.8.01",
      parentSha256 = "74ada31575d1b4d9235403e894be359842e9b5f0a76044b450be7f751c5860d9",
      compatibilityApi = 34,
      diagnosticsApi = 1,
  }
  -- 2.6.57: central fail-soft install / hook / feature-health foundation.
  -- Existing attemptInstall(name, fn, ...) callers remain source-compatible,
  -- while new callers may pass a descriptor table with feature/required/mode
  -- metadata.  An explicit installer `false` is now diagnostic failure rather
  -- than a pcall success.  This changes observability only: optional failures
  -- remain fail-soft and do not mutate rule state.
  mod.exports.__beta26.installHealth = {
      api = 3, attempts = {}, failures = {}, skipped = {}, log = {}, max_log = 96,
  }
  mod.exports.__beta26.featureHealth = {
      api = 1, ACTIVE = "ACTIVE", DEGRADED = "DEGRADED",
      UNAVAILABLE = "UNAVAILABLE", PENDING = "PENDING",
      NOT_APPLICABLE = "N/A", features = {},
  }
  mod.exports.__beta26.hookRegistry = { api = 1, hooks = {} }

  function mod.exports.__beta26.noteFeatureHealth(feature, state, reason, source)
      feature = tostring(feature or "unknown")
      state = tostring(state or "ACTIVE")
      if state ~= "ACTIVE" and state ~= "DEGRADED"
          and state ~= "UNAVAILABLE" and state ~= "PENDING"
          and state ~= "N/A" then state = "DEGRADED" end
      local row = mod.exports.__beta26.featureHealth.features[feature] or {
          feature = feature, transitions = 0,
      }
      row.transitions = (tonumber(row.transitions) or 0) + 1
      row.state, row.reason, row.source = state,
          reason and tostring(reason) or nil, source and tostring(source) or nil
      mod.exports.__beta26.featureHealth.features[feature] = row
      return row
  end

  function mod.exports.__beta26.featureHealth.status(feature)
      if feature ~= nil then
          local row = mod.exports.__beta26.featureHealth.features[tostring(feature)]
          if type(row) ~= "table" then return nil end
          return { feature=row.feature, state=row.state, reason=row.reason,
              source=row.source, transitions=row.transitions }
      end
      local out = {}
      for key, row in pairs(mod.exports.__beta26.featureHealth.features) do
          out[key] = { feature=row.feature, state=row.state, reason=row.reason,
              source=row.source, transitions=row.transitions }
      end
      return out
  end

  function mod.exports.__beta26.registerHook(id, meta)
      id, meta = tostring(id or "unknown"), type(meta) == "table" and meta or {}
      local row = mod.exports.__beta26.hookRegistry.hooks[id] or { id=id, registrations=0 }
      row.registrations = (tonumber(row.registrations) or 0) + 1
      row.owner = tostring(meta.owner or "nuzlocke")
      row.priority = tonumber(meta.priority) or 100
      row.mode = tostring(meta.mode or "wrap")
      row.feature = tostring(meta.feature or id)
      row.previous = meta.previous
      row.wrapper = meta.wrapper
      row.live = meta.live
      row.source = meta.source and tostring(meta.source) or nil
      mod.exports.__beta26.hookRegistry.hooks[id] = row
      return row
  end

  function mod.exports.__beta26.hookRegistry.describe()
      local out = {}
      for id, row in pairs(mod.exports.__beta26.hookRegistry.hooks) do
          local live = nil
          if type(row.live) == "function" then
              local ok, value = pcall(row.live)
              live = ok and value == true or false
          end
          out[id] = { id=id, owner=row.owner, priority=row.priority,
              mode=row.mode, feature=row.feature, source=row.source,
              registrations=row.registrations, previous_type=type(row.previous),
              wrapper_type=type(row.wrapper), live=live }
      end
      return out
  end

  function mod.exports.__beta26.hookRegistry.audit()
      local report = { ok=true, checked=0, failures={}, warnings={} }
      for id, row in pairs(mod.exports.__beta26.hookRegistry.hooks) do
          report.checked = report.checked + 1
          local ok = row.owner == "nuzlocke" and type(row.mode) == "string"
              and tonumber(row.priority) ~= nil
          if ok and row.wrapper ~= nil then ok = type(row.wrapper) == "function" end
          if not ok then
              report.ok = false
              report.failures[#report.failures + 1] = tostring(id)
          elseif type(row.live) == "function" then
              local callOk, isLive = pcall(row.live)
              if not callOk then
                  report.ok = false
                  report.failures[#report.failures + 1] = tostring(id) .. ":live_probe_error"
              elseif isLive ~= true then
                  -- Another mod may legitimately compose above our wrapper.
                  -- Record the interposition but do not make composition itself
                  -- a release-fatal error; Dev Hook Health owns CHAINED detail.
                  report.warnings[#report.warnings + 1] = tostring(id) .. ":chained"
              end
          end
      end
      return report
  end

  function mod.exports.__beta26.safeInstall(spec, fn, ...)
      spec = type(spec) == "table" and spec or { id = spec }
      local name = tostring(spec.id or spec.name or "unknown")
      local feature = tostring(spec.feature or name)
      local required = spec.required == true
      local health = mod.exports.__beta26.installHealth
      local row = health.attempts[name] or { attempts=0, id=name }
      health.attempts[name] = row
      row.attempts = row.attempts + 1
      row.feature, row.required, row.mode = feature, required,
          tostring(spec.mode or "installer")
      row.edition = nil
      row.edition_probe_error = nil
      if mod.exports.__beta26.Dev and mod.exports.__beta26.Dev.gameId then
          local okEdition, editionOrError = pcall(
              mod.exports.__beta26.Dev.gameId, currentGame or mod.game)
          if okEdition then
              row.edition = editionOrError
          else
              row.edition_probe_error = tostring(editionOrError)
          end
      end
      local function fail(reason)
          reason = tostring(reason or "unknown_error")
          row.ok, row.status, row.error = false, "FAIL", reason
          health.failures[name] = reason
          health.skipped[name] = nil
          local prefix = "[Nuzlocke:" .. name .. "] " .. reason
          health.log[#health.log + 1] = prefix
          while #health.log > health.max_log do table.remove(health.log, 1) end
          mod.exports.__beta26.noteFeatureHealth(feature,
              required and "UNAVAILABLE" or "DEGRADED", reason, name)
          return false, reason
      end
      local function skip(kind, reason)
          kind = tostring(kind or "N/A")
          reason = tostring(reason or "not_applicable")
          row.ok, row.status, row.error = true, kind, nil
          row.note = reason
          health.failures[name] = nil
          health.skipped[name] = kind .. ":" .. reason
          mod.exports.__beta26.noteFeatureHealth(feature, kind,
              reason, name)
          return true, kind, reason
      end
      if type(fn) ~= "function" then return fail("installer_not_function") end
      local results = { pcall(fn, ...) }
      local callOk = table.remove(results, 1)
      if not callOk then return fail(results[1]) end
      if results[1] == false then
          if results[2] == "not_applicable" then
              return skip("N/A", results[3] or "optional dependency absent")
          elseif results[2] == "pending" then
              return skip("PENDING", results[3] or "dependency/module not loaded")
          end
          return fail(results[2] or "installer_returned_false")
      end
      row.ok, row.status, row.error, row.note = true, "ACTIVE", nil, nil
      health.failures[name] = nil
      health.skipped[name] = nil
      mod.exports.__beta26.noteFeatureHealth(feature, "ACTIVE", nil, name)
      mod.exports.__beta26.registerHook("installer:" .. name, {
          owner="nuzlocke", priority=spec.priority or 100,
          mode=spec.mode or "installer", feature=feature, source=name,
      })
      return true, unpackValues(results)
  end

  function mod.exports.__beta26.attemptInstall(name, fn, ...)
      return mod.exports.__beta26.safeInstall(name, fn, ...)
  end

  local function compatPublicCopy(value, seen)
      if type(value) ~= "table" then return value end
      seen = seen or {}
      if seen[value] then return seen[value] end
      local out = {}
      seen[value] = out
      for key, item in pairs(value) do
          out[compatPublicCopy(key, seen)] = compatPublicCopy(item, seen)
      end
      return out
  end

  -- 2.2.9 canonical native stat-vitamin data. R/B/Y and Gold use the
  -- same five vitamins; Zinc is not a Gen II item.
  mod.exports.__beta26.nativeStatVitamins = {
      "HP_UP", "PROTEIN", "IRON", "CARBOS", "CALCIUM",
  }
  mod.exports.__beta26.nativeStatVitaminSet = {
      HP_UP = true, PROTEIN = true, IRON = true, CARBOS = true,
      CALCIUM = true,
  }
  mod.exports.__beta25 = mod.exports.__beta26

  -- 2.5.37: save.boxes is legitimately sparse on Gold because individual
  -- boxes are materialized only when used. Lua ipairs() stops at the first
  -- nil index, so every cross-box Nuzlocke scan must enumerate the existing
  -- numeric slots explicitly rather than assuming a dense array. Keep the
  -- traversal stable by numeric box index; returning false from the callback
  -- stops early for find-style callers.
  mod.exports.__beta26.forEachExistingSaveBox = function(save, callback)
      if type(save) ~= "table" or type(save.boxes) ~= "table"
          or type(callback) ~= "function" then return true end
      local slots = {}
      for key, box in pairs(save.boxes) do
          local index = tonumber(key)
          if index and index >= 1 and index == math.floor(index)
              and type(box) == "table" then
              slots[#slots + 1] = { index = index, key = key, box = box }
          end
      end
      table.sort(slots, function(a, b)
          if a.index == b.index then return tostring(a.key) < tostring(b.key) end
          return a.index < b.index
      end)
      local seen = {}
      for _, row in ipairs(slots) do
          if not seen[row.index] then
              seen[row.index] = true
              if callback(row.box, row.index) == false then return false end
          end
      end
      return true
  end

  -- beta.27.4: Gen1Recomp's embedded Save Editor creates its own ModLoader
  -- inside the same Lua process. Runtime monkey patches installed from that
  -- editor loader can otherwise survive App.unload() in package.loaded and
  -- retain the editor session's mod.save closure when gameplay starts.
  -- Detect the editor without requiring its module: App.load has already put
  -- the flat `App` module in package.loaded and getState() is non-nil only
  -- while the editor session is actually open.
  mod.exports.__beta26.isSaveEditorSession = function()
      local loaded = package and package.loaded and package.loaded["App"]
      if type(loaded) ~= "table" or type(loaded.getState) ~= "function" then
          return false
      end
      local ok, state = pcall(loaded.getState)
      return ok and state ~= nil
  end
  mod.exports.__beta26.runtimeEnvironment = function()
      return mod.exports.__beta26.isSaveEditorSession() and "save_editor" or "gameplay"
  end

  -- beta.30.0.0.18: Permanent Rule Seal is stronger than an ordinary
  -- mod.save preference. Gen1Recomp keeps mod.save inside the normal Pokemon
  -- progress record, so quitting before the next in-game SAVE can roll it
  -- back. Mirror only this irreversible bit into playthrough-scoped
  -- mod.storage so commitment is durable immediately.
  -- beta.30.0.0.19: Permanent Rule Seal is temporarily WIP-disabled.
  -- Keep the complete activation/persistence implementation below intact so it
  -- can be recovered deliberately after more persistence/runtime design work.
  -- While this flag is true the row is grey/unselectable, existing test seals
  -- are not enforced, and their durable marker is preserved rather than erased.
  mod.exports.__beta26.permanentRuleSealWip = true
  mod.exports.__beta26.permanentRuleSealStorageKey = "rules/permanent_seal"

  mod.exports.__beta26.persistPermanentRuleSeal = function(game)
      if not mod.storage or type(mod.storage.write) ~= "function" then
          return false, "storage_unavailable"
      end
      game = game or currentGame or mod.game
      if not game then return false, "not_in_playthrough" end
      local ok, written, code = mod.exports.__beta26.Dev.pguard(
          "storage_write_permanent_seal", mod.storage.write, mod.storage, game,
          mod.exports.__beta26.permanentRuleSealStorageKey,
          { format = 1, sealed = true })
      if not ok then return false, "write_failed" end
      if written ~= true then return false, code or "write_failed" end
      mod.save:set("rules_locked", true)
      mod.save:set("rules_permanently_locked", true)
      return true
  end

  mod.exports.__beta26.readPermanentRuleSeal = function(game)
      if mod.save:get("rules_permanently_locked", false) == true then
          return true, "mod_save"
      end
      if not mod.storage or type(mod.storage.read) ~= "function" then
          return false, "storage_unavailable"
      end
      game = game or currentGame or mod.game
      if not game then return false, "not_in_playthrough" end
      local ok, payload, code = mod.exports.__beta26.Dev.pguard(
          "storage_read_permanent_seal", mod.storage.read, mod.storage, game,
          mod.exports.__beta26.permanentRuleSealStorageKey)
      if not ok then return false, "read_failed" end
      if type(payload) == "table" and payload.sealed == true then
          return true, "storage"
      end
      return false, code or "not_found"
  end

  -- 2.3.10 boot hardening: Yellow 0.1.98 runtime-confirmed that the
  -- initializer + Strings/title UI path is safe. Stats/Growth are not needed
  -- until Pokemon/rule evaluation, so do not import them during pre-title mod
  -- initialization.
  mod.exports.__beta26.getStatsModule = function()
      local ok, module = pcall(require, "src.pokemon.Stats")
      if ok and type(module) == "table" then return module end
      return nil
  end
  mod.exports.__beta26.getGrowthModule = function()
      local ok, module = pcall(require, "src.pokemon.Growth")
      if ok and type(module) == "table" then return module end
      return nil
  end
  local Strings = require("src.core.Strings")
  local H = {} -- private helper namespace; reduces outer local pressure
  -- 2.4.80 localization compliance: measure translated text by rendered
  -- glyph spans rather than Lua byte length. This keeps accented/custom
  -- charmap glyphs intact when Nuzlocke wraps or slices its own UI text.
  local function nuzGlyphSpans(text)
      text = tostring(text or "")
      local ok, Font = pcall(require, "src.render.Font")
      if ok and Font and type(Font.split) == "function" then
          local spans = Font.split(text)
          if type(spans) == "table" then return spans end
      end
      local spans = {}
      local okUtf8, utf8lib = pcall(require, "utf8")
      if okUtf8 and utf8lib and type(utf8lib.codes) == "function" then
          local starts = {}
          for pos in utf8lib.codes(text) do starts[#starts + 1] = pos end
          for i, pos in ipairs(starts) do
              spans[i] = { from = pos, to = (starts[i + 1] or (#text + 1)) - 1 }
          end
      else
          for i = 1, #text do spans[i] = { from = i, to = i } end
      end
      return spans
  end

  local function nuzGlyphLen(text)
      return #nuzGlyphSpans(text)
  end

  local function nuzGlyphSlice(text, first, last)
      text = tostring(text or "")
      local spans = nuzGlyphSpans(text)
      if #spans == 0 then return "" end
      first = math.max(1, tonumber(first) or 1)
      last = math.min(#spans, tonumber(last) or #spans)
      if first > last or not spans[first] or not spans[last] then return "" end
      return text:sub(spans[first].from, spans[last].to)
  end
  -- Public, generation-neutral localization seam for companion mods and
  -- translator test harnesses. English source text remains the stable key;
  -- missing entries safely fall back through the engine's Strings module.
  mod.exports.nuzlocke_translation = {
      api = 1,
      build = mod.exports.__beta26.build,
      get = function(source, ...)
          return Strings(source, ...)
      end,
      source = function(text)
          return Strings.source(text)
      end,
       known_companions = {
          ["gen1_pt-br"] = {
              name = "(PT-BR) Versao Brasileira",
              reviewed = "0.1.4",
              behavior = "localization_only",
          },
          ["finnish"] = {
              name = "Suomi",
              reviewed = "0.1.0",
              behavior = "localization_only",
          },
      },
  }
  -- 2.3.22 generic presentation-owner contract.
  -- UI overhauls may replace how Nuzlocke screens are drawn, but Nuzlocke
  -- remains the owner of their state/actions.  This is intentionally
  -- provider-neutral so presentation mods do not need hardcoded Nuzlocke
  -- screen-name heuristics and Nuzlocke does not need mod-id branches.
  mod.exports.nuzlocke_ui = {
      api = 2,
      build = mod.exports.__beta26.build,
      stateOwner = "nuzlocke",
      screens = {
          NuzlockeConfigScreen = {
              role = "rules",
              stateOwner = "nuzlocke",
              preferredLayout = "adaptive",
              nativeFallback = true,
              semanticAdapterSafe = true,
          },
          NuzlockeTrackerScreen = {
              role = "tracker",
              stateOwner = "nuzlocke",
              preferredLayout = "adaptive",
              nativeFallback = true,
              semanticAdapterSafe = true,
          },
          NuzlockeModCompatScreen = {
              role = "compatibility_status",
              stateOwner = "nuzlocke",
              preferredLayout = "wide",
              nativeFallback = true,
              semanticAdapterSafe = true,
          },
          NuzlockeForgivenessItem = {
              role = "forgiveness",
              stateOwner = "nuzlocke",
              preferredLayout = "centered",
              nativeFallback = true,
              semanticAdapterSafe = false,
          },
          NuzlockeForgivenessRevive = {
              role = "forgiveness_revive",
              stateOwner = "nuzlocke",
              preferredLayout = "centered",
              nativeFallback = true,
              semanticAdapterSafe = false,
          },
          NuzlockeForgivenessArea = {
              role = "forgiveness_area",
              stateOwner = "nuzlocke",
              preferredLayout = "centered",
              nativeFallback = true,
              semanticAdapterSafe = false,
          },
          NuzlockeDevToolsScreen = {
              role = "developer_tools",
              stateOwner = "nuzlocke",
              preferredLayout = "centered",
              nativeFallback = true,
              semanticAdapterSafe = false,
          },
          NuzlockeUiGalleryScreen = {
              role = "ui_gallery",
              stateOwner = "nuzlocke",
              preferredLayout = "adaptive",
              nativeFallback = true,
              semanticAdapterSafe = false,
          },
      },
  }

  mod.exports.nuzlocke_ui.describeScreen = function(screenOrId)
      local id = type(screenOrId) == "table"
          and (screenOrId.screenId or screenOrId.id) or screenOrId
      local row = id and mod.exports.nuzlocke_ui.screens[tostring(id)] or nil
      if type(row) ~= "table" then return nil end
      local out = {}
      for key, value in pairs(row) do out[key] = value end
      out.id = tostring(id)
      out.api = mod.exports.nuzlocke_ui.api
      return out
  end

  mod.exports.nuzlocke_translation.detect = function()
      local out = {}
      for id, meta in pairs(mod.exports.nuzlocke_translation.known_companions) do
          local ok, other = pcall(mod.find, id)
          if ok and type(other) == "table" then
              out[#out + 1] = {
                  id = id,
                  name = other.name or (other.manifest and other.manifest.name)
                      or meta.name,
                  version = other.version or (other.manifest and other.manifest.version),
                  reviewed = meta.reviewed,
                  behavior = meta.behavior,
                  semanticUiMatching = true,
                  nativeTrainerCardOwnedByTranslation = id == "gen1_pt-br",
                  trainerCardOverrideEnabled = id == "gen1_pt-br"
                      and type(other.exports) == "table"
                      and other.exports.trainer_card == true or false,
                  inventoryLineBreakEnabled = id == "gen1_pt-br"
                      and type(other.exports) == "table"
                      and other.exports.precos_linha == true or false,
              }
          end
      end
      return out
  end
  mod.events:on("mods.loaded", function()
      for _, row in ipairs(mod.exports.nuzlocke_translation.detect()) do
          if mod.log and type(mod.log.info) == "function" then
              mod.log:info("[Nuzlocke:Compat] translation companion detected: %s %s (reviewed %s)",
                  tostring(row.id), tostring(row.version or "?"),
                  tostring(row.reviewed or "?"))
          end
      end
  end)
  local catchDeniedReason
  local isTownArea
  local enemyIsShiny
  local currentSave
  local refreshGymGuideVisibility
  local getGameVersion
  local getDisplayRoutes
  local getEncounterState
  local LEGENDARIES, MYTHICALS, PSEUDOS
  local finalizeNuzlockeBattle
  local evaluateItemUsePolicy
  local externalRuleDelegation
  local NON_CORE_DELEGATION
  local specialAcquisitionDenied
  local active
  local ItemPolicy
  -- 2.7.84: source-audit the Gen1Recomp compatibility/documentation surface
  -- through the 0.2.25 line. Mod API 2, save format 4 and the existing
  -- engine range remain valid. Crystal is now an intentional Nuzlocke target,
  -- but is explicitly ALPHA and carries independent runtime evidence.
  mod.exports.__beta26.recompCompatAudited = "0.2.25"
  mod.exports.__beta26.crystalSupport = {
      stage = "ALPHA", runtime_certified = false,
      note = "Crystal support is experimental; shared Gen-2 rules are enabled, but Crystal-specific systems require independent runtime certification.",
  }
  mod.exports.__beta26.wonderlockeWip = true

  ---------------------------------------------------------------------
  -- FUTURE-SAFE SAVE SCHEMA
  --
  -- This layer is intentionally additive and independent of the Lua/mod
  -- version.  A save can skip releases, have the mod removed/reinstalled,
  -- or be loaded by a newer build without being mistaken for a new run.
  -- Migrations are idempotent and never delete or rewrite existing Nuzlocke
  -- gameplay data.  A newer schema is left untouched by older builds.
  ---------------------------------------------------------------------
  local SAVE_SCHEMA_KEY = "__nuzlocke_save_schema"
  local SAVE_MIGRATION_KEY = "__nuzlocke_last_migration"
  local CURRENT_SAVE_SCHEMA = 5
  local saveSchemaTooNew = false
  local saveMigrationError = nil

  -- 2.4.63 downgrade safety + 2.5.78 migration-integrity pause.  Once a save
  -- declares a schema newer than this build understands OR a migration cannot
  -- complete/recover safely, ordinary Nuzlocke persistence/enforcement becomes
  -- read-only instead of interpreting uncertain state through older assumptions.
  mod.exports.__beta26.saveWritePauseReason = function()
      if saveSchemaTooNew == true then return "newer_schema" end
      if saveMigrationError ~= nil then return "migration_error" end
      return nil
  end

  mod.exports.__beta26.saveSchemaSupported = function()
      return mod.exports.__beta26.saveWritePauseReason() == nil
  end

  -- 2.4.66/2.4.70 central save-write barrier, extended in 2.5.78 to migration
  -- failures. Explicit subsystem guards remain the primary protection mechanism.
  -- If an unguarded Nuzlocke path still reaches mod.save:set while persistence
  -- is paused, record the attempt and refuse the write. This is the last-line
  -- invariant preventing uncertain state from being modified further.
  mod.exports.__beta26.safeStopWrites =
      mod.exports.__beta26.safeStopWrites or {
          total = 0,
          byKey = {},
          firstKey = nil,
          lastKey = nil,
      }

  mod.exports.__beta26.safeStopWriteReport = function()
      local state = mod.exports.__beta26.safeStopWrites or {}
      local byKey = {}
      for key, count in pairs(state.byKey or {}) do
          byKey[tostring(key)] = tonumber(count) or 0
      end
      return {
          active = mod.exports.__beta26.saveWritePauseReason() ~= nil,
          reason = mod.exports.__beta26.saveWritePauseReason(),
          total = tonumber(state.total) or 0,
          by_key = byKey,
          first_key = state.firstKey,
          last_key = state.lastKey,
      }
  end

  mod.exports.__beta26.resetSafeStopWrites = function()
      mod.exports.__beta26.safeStopWrites = {
          total = 0,
          byKey = {},
          firstKey = nil,
          lastKey = nil,
      }
      return true
  end

  do
      local saveApi = mod.save
      if type(saveApi) == "table" and type(saveApi.set) == "function" then
          local session = saveApi.__nuzlockeSafeStopWriteSession
          if not (type(session) == "table" and session.owner == mod
              and saveApi.set == session.wrapper) then
              if type(session) == "table" and saveApi.set == session.wrapper
                  and type(session.previous) == "function" then
                  saveApi.set = session.previous
              end
              local previous = saveApi.set
              local wrapper
              wrapper = function(self, key, value, ...)
                  local pauseReason =
                      mod.exports.__beta26.saveWritePauseReason()
                  if pauseReason ~= nil then
                      local state = mod.exports.__beta26.safeStopWrites
                      if type(state) ~= "table" then
                          state = { total=0, byKey={}, firstKey=nil, lastKey=nil }
                          mod.exports.__beta26.safeStopWrites = state
                      end
                      state.byKey = type(state.byKey) == "table" and state.byKey or {}
                      local name = tostring(key or "<nil>")
                      state.total = (tonumber(state.total) or 0) + 1
                      state.byKey[name] = (tonumber(state.byKey[name]) or 0) + 1
                      state.firstKey = state.firstKey or name
                      state.lastKey = name

                      local dev = mod.exports.__beta26.Dev
                      if type(dev) == "table" and type(dev.enabled) == "function"
                          and type(dev.push) == "function"
                          and dev.enabled() and state.byKey[name] == 1 then
                          dev.push("safe_stop.write_attempt",
                              name .. " blocked while save writes are paused ("
                                  .. tostring(pauseReason) .. ")",
                              currentGame or mod.game)
                      end
                      return false, pauseReason
                  end
                  return previous(self, key, value, ...)
              end
              saveApi.set = wrapper
              saveApi.__nuzlockeSafeStopWriteSession = {
                  owner = mod, previous = previous, wrapper = wrapper,
              }
              -- Historical markers remain compatibility/debug metadata only.
              saveApi.__nuzlockeSafeStopWriteOwner = mod
              saveApi.__nuzlockeSafeStopWritePrevious = previous
              saveApi.__nuzlockeSafeStopWriteFunction = wrapper
          end
      end
  end

  -- 2.2.15: one coordinator owns every save upgrade that must happen before
  -- normal save.loaded consumers see canonical Nuzlocke state. Keep the plan
  -- on the existing export namespace instead of growing the main chunk's local
  -- count; compiler-budget headroom is a release invariant for this project.
  mod.exports.__beta26.saveUpgrade = {
      phaseOrder = { "schema", "semantic", "reconstruction", "projection" },
      steps = { schema = {}, semantic = {}, reconstruction = {}, projection = {} },
      ids = {},
      lastRun = nil,
      -- 2.5.78: schema transitions use a durable write-ahead journal.  The
      -- key is Nuzlocke-reserved and optional under schema 4; it is cleared
      -- after a clean commit and therefore does not change rule semantics.
      transactionKey = "__nuzlocke_schema_migration_txn",
      backupDepth = 3,
      backupSuffix = ".nuzlocke-pre-migration",
      lastBackup = nil,
  }

  mod.exports.__beta26.registerSaveUpgradeStep = function(phase, id, fn)
      local upgrade = mod.exports.__beta26.saveUpgrade
      local bucket = upgrade and upgrade.steps and upgrade.steps[phase]
      id = tostring(id or "")
      if type(bucket) ~= "table" or id == "" or type(fn) ~= "function" then
          return false, "invalid save-upgrade registration"
      end
      if upgrade.ids[id] then
          return false, "duplicate save-upgrade id: " .. id
      end
      upgrade.ids[id] = phase
      bucket[#bucket + 1] = { id = id, run = fn }
      return true
  end

  -- Explicit destination-version migrators. A marker-only step is still a
  -- real entry so bumping CURRENT_SAVE_SCHEMA without defining vN cannot
  -- silently skip a transition.
  mod.exports.__beta26.saveUpgrade.schemaMigrations = {
      [1] = function(store)
          return true -- baseline marker only
      end,
      [2] = function(store)
          store = store or mod.save
          -- An older save must never revive the unfinished Wonderlocke path.
          store:set("wonderlocke", false)
          return true
      end,
      [3] = function(store)
          -- Persistent Pokemon IDs are intentionally assigned during the
          -- reconstruction phase, where party/box/provider identity is known.
          return true
      end,
      [4] = function(store)
          store = store or mod.save
          local oldShop = store:get("no_shopping", nil)
          if type(oldShop) == "boolean" then
              if store:get("no_buying", nil) == nil then
                  store:set("no_buying", oldShop)
              end
              if store:get("no_selling", nil) == nil then
                  store:set("no_selling", oldShop)
              end
          end

          local oldDupes = store:get("dupes_mode", nil)
          if type(oldDupes) == "boolean" then
              store:set("dupes_mode", oldDupes and 2 or 0)
          end
          return true
      end,
      [5] = function(store)
          store = store or mod.save
          if store:get("shop_restrictions", nil) == nil then
              local noBuy = store:get("no_buying", false) == true
              local noSell = store:get("no_selling", false) == true
              local mode = noBuy and (noSell and 3 or 1) or (noSell and 2 or 0)
              store:set("shop_restrictions", mode)
          end
          return true
      end,
  }

  -- 2.7.7: loading shipped split modules is a required Mod API file-read use,
  -- distinct from optional diagnostic source introspection. Gen1Recomp exposes
  -- mod:read(relative) for files in this mod; arbitrary require() of mod-local
  -- files is not the public module-loading contract. Centralize the required
  -- read/compile boundary so failures are explicit and never confused with the
  -- fail-soft policy for later source-lint rereads.
  local function loadRequiredModuleChunk(path)
      path = tostring(path or "")
      local okRead, source, readErr = pcall(mod.read, mod, path)
      if not okRead then
          error("required Nuzlocke module read failed (" .. path .. "): "
              .. tostring(source), 2)
      end
      if type(source) ~= "string" then
          error("required Nuzlocke module unavailable (" .. path .. "): "
              .. tostring(readErr or "mod:read returned no source"), 2)
      end
      local chunk, loadErr = load(source, "@mods/nuzlocke/" .. path)
      if type(chunk) ~= "function" then
          error("required Nuzlocke module compile failed (" .. path .. "): "
              .. tostring(loadErr or "unknown compile error"), 2)
      end
      return chunk
  end

  -- 2.5.80: isolate the shadow migration store first; transaction orchestration
  -- remains in main.lua until exact-engine historical-save tests protect a larger move.
  loadRequiredModuleChunk("save_migration.lua")()(mod, {
      copy = compatPublicCopy,
      SAVE_SCHEMA_KEY = SAVE_SCHEMA_KEY,
      SAVE_MIGRATION_KEY = SAVE_MIGRATION_KEY,
  })

  -- 2.5.78: bounded whole-save snapshots before any numbered schema mutation.
  -- Gen1Recomp owns the authoritative save path/filesystem and already keeps
  -- its own .bak/.tmp recovery.  These three Nuzlocke snapshots are separate
  -- and slot/edition-specific because they derive from SaveData.saveFilename.
  -- Backup failure is diagnostic rather than destructive: the transaction
  -- layer still protects in-memory migration semantics and the engine retains
  -- its native rolling backup.
  mod.exports.__beta26.saveUpgrade.createPreMigrationBackup = function(game, save)
      local upgrade = mod.exports.__beta26.saveUpgrade
      game = game or currentGame or mod.game
      save = save or currentSave or (game and game.save)
      local okSave, SaveData = pcall(require, "src.core.SaveData")
      if not okSave or type(SaveData) ~= "table"
          or type(SaveData.saveFilename) ~= "function"
          or type(SaveData.persistenceFs) ~= "function" then
          upgrade.lastBackup = { ok=false, reason="SaveData unavailable" }
          return false, "SaveData unavailable"
      end
      local version = save and save.version or nil
      if version == nil then
          local okVersion, GameVersion = pcall(require, "src.core.GameVersion")
          if okVersion and GameVersion and type(GameVersion.get) == "function" then
              local okGet, detected = pcall(GameVersion.get)
              if okGet then version = detected end
          end
      end
      if version == nil then
          upgrade.lastBackup = { ok=false, reason="game version unavailable" }
          return false, "game version unavailable"
      end
      local okName, mainName = pcall(SaveData.saveFilename, version)
      local okFs, fs = pcall(SaveData.persistenceFs)
      if not okName or type(mainName) ~= "string" or mainName == ""
          or not okFs or type(fs) ~= "table"
          or type(fs.read) ~= "function" or type(fs.write) ~= "function" then
          upgrade.lastBackup = { ok=false, reason="persistence surface unavailable" }
          return false, "persistence surface unavailable"
      end

      local sourceName, body = mainName, nil
      for _, candidate in ipairs({ mainName, mainName .. ".tmp", mainName .. ".bak" }) do
          local okRead, value = pcall(fs.read, candidate)
          if okRead and type(value) == "string" and #value > 0 then
              sourceName, body = candidate, value
              break
          end
      end
      if type(body) ~= "string" or #body == 0 then
          upgrade.lastBackup = { ok=false, reason="no readable save source",
              save_file=mainName, game_version=tostring(version) }
          return false, "no readable save source"
      end

      local base = mainName .. upgrade.backupSuffix
      local staged = base .. ".new"
      local okStage, stageResult = pcall(fs.write, staged, body)
      if not okStage or stageResult == false then
          upgrade.lastBackup = { ok=false, reason="backup stage write failed",
              save_file=mainName, game_version=tostring(version) }
          return false, "backup stage write failed"
      end
      local okVerify, stagedBody = pcall(fs.read, staged)
      if not okVerify or stagedBody ~= body then
          upgrade.lastBackup = { ok=false, reason="backup stage verify failed",
              save_file=mainName, game_version=tostring(version) }
          return false, "backup stage verify failed"
      end

      local depth = math.max(1, math.min(8,
          math.floor(tonumber(upgrade.backupDepth) or 3)))
      local firstName = base .. ".1"
      local okExisting, existingBody = pcall(fs.read, firstName)
      if okExisting and existingBody == body then
          if type(fs.remove) == "function" then pcall(fs.remove, staged) end
          upgrade.lastBackup = { ok=true, depth=depth, bytes=#body, reused=true,
              save_file=mainName, source_file=sourceName,
              game_version=tostring(version), first=firstName }
          return true, compatPublicCopy(upgrade.lastBackup)
      end
      for i = depth, 2, -1 do
          local previousName = base .. "." .. tostring(i - 1)
          local nextName = base .. "." .. tostring(i)
          local okRead, previousBody = pcall(fs.read, previousName)
          if okRead and type(previousBody) == "string" then
              local okWrite, writeResult = pcall(fs.write, nextName, previousBody)
              if not okWrite or writeResult == false then
                  upgrade.lastBackup = { ok=false, reason="backup rotation failed",
                      save_file=mainName, game_version=tostring(version) }
                  return false, "backup rotation failed"
              end
          elseif type(fs.remove) == "function" then
              pcall(fs.remove, nextName)
          end
      end
      local okWrite, writeResult = pcall(fs.write, firstName, body)
      if not okWrite or writeResult == false then
          upgrade.lastBackup = { ok=false, reason="backup write failed",
              save_file=mainName, game_version=tostring(version) }
          return false, "backup write failed"
      end
      local okFirst, firstBody = pcall(fs.read, firstName)
      if not okFirst or firstBody ~= body then
          upgrade.lastBackup = { ok=false, reason="backup verify failed",
              save_file=mainName, game_version=tostring(version) }
          return false, "backup verify failed"
      end
      if type(fs.remove) == "function" then pcall(fs.remove, staged) end
      upgrade.lastBackup = { ok=true, depth=depth, bytes=#body,
          save_file=mainName, source_file=sourceName,
          game_version=tostring(version), first=firstName }
      return true, compatPublicCopy(upgrade.lastBackup)
  end

  mod.exports.__beta26.saveUpgrade.previewPendingSchemaMigrations = function()
      local upgrade = mod.exports.__beta26.saveUpgrade
      local pending = mod.save:get(upgrade.transactionKey, nil)
      if type(pending) == "table" then
          return { ok=false, stopped="pending_transaction",
              transaction_target=pending.target_schema, steps={}, writes={} }
      end
      local rawVersion = mod.save:get(SAVE_SCHEMA_KEY, nil)
      local version = tonumber(rawVersion)
      if version == nil then version = 0 end
      version = math.floor(version)
      if version > CURRENT_SAVE_SCHEMA then
          return { ok=false, stopped="newer_schema", from_schema=version,
              to_schema=CURRENT_SAVE_SCHEMA, steps={}, writes={} }
      end
      local shadow = mod.exports.__beta26.saveUpgrade.newShadowStore(mod.save)
      local report = { ok=true, from_schema=version, to_schema=CURRENT_SAVE_SCHEMA,
          steps={}, writes={} }
      while version < CURRENT_SAVE_SCHEMA do
          local target = version + 1
          local migrate = mod.exports.__beta26.saveUpgrade.schemaMigrations[target]
          if type(migrate) ~= "function" then
              report.ok = false
              report.failed = "missing schema migration v" .. tostring(target)
              return report
          end
          local ok, result = pcall(migrate, shadow)
          if not ok or result == false then
              report.ok = false
              report.failed = ok and ("schema migration v" .. tostring(target)
                  .. " declined") or tostring(result)
              return report
          end
          shadow:set(SAVE_SCHEMA_KEY, target)
          shadow:set(SAVE_MIGRATION_KEY, "v" .. tostring(target))
          report.steps[#report.steps + 1] = "v" .. tostring(target)
          version = target
      end
      report.writes = shadow:changes()
      report.write_count = #report.writes
      return report
  end

  mod.exports.__beta26.saveUpgrade.recoverSchemaTransaction = function(version)
      local upgrade = mod.exports.__beta26.saveUpgrade
      local txn = mod.save:get(upgrade.transactionKey, nil)
      if type(txn) ~= "table" then
          return true, "none"
      end
      local target = math.floor(tonumber(txn.target_schema) or -1)
      if tonumber(txn.api) ~= 1 or type(txn.writes) ~= "table" then
          return false, "invalid_transaction"
      end
      version = math.floor(tonumber(version) or
          tonumber(mod.save:get(SAVE_SCHEMA_KEY, 0)) or 0)
      if target < 0 then
          return false, "invalid_transaction"
      end
      if target > CURRENT_SAVE_SCHEMA then
          return false, "newer_transaction"
      end

      -- If the schema marker reached the target, the write set committed and
      -- only cleanup was interrupted.  Finish the checkpoint and clear the
      -- journal; rolling back here would corrupt an already-committed schema.
      if version >= target then
          local checkpointOk, checkpointResult = pcall(mod.save.set, mod.save,
              SAVE_MIGRATION_KEY, "v" .. tostring(target))
          if not checkpointOk or checkpointResult == false then
              return false, "commit_cleanup_failed"
          end
          local clearOk, clearResult = pcall(mod.save.set, mod.save,
              upgrade.transactionKey, nil)
          if not clearOk or clearResult == false then
              return false, "transaction_clear_failed"
          end
          return true, "commit_cleanup"
      end

      -- Otherwise the process stopped before the schema marker was committed.
      -- Restore every touched key to the state recorded before application.
      -- Never clear the journal unless every rollback write succeeds.
      local writes = type(txn.writes) == "table" and txn.writes or {}
      for i = #writes, 1, -1 do
          local row = writes[i]
          if type(row) == "table" and row.key ~= nil then
              local rollbackOk, rollbackResult = pcall(mod.save.set, mod.save,
                  row.key, row.before_present and row.before_value or nil)
              if not rollbackOk or rollbackResult == false then
                  return false, "rollback_failed:" .. tostring(row.key)
              end
          end
      end
      local clearOk, clearResult = pcall(mod.save.set, mod.save,
          upgrade.transactionKey, nil)
      if not clearOk or clearResult == false then
          return false, "transaction_clear_failed"
      end
      return true, "rolled_back"
  end

  mod.exports.__beta26.saveUpgrade.applySchemaMigration = function(fromVersion, target, migrate)
      local upgrade = mod.exports.__beta26.saveUpgrade
      fromVersion = math.floor(tonumber(fromVersion) or -1)
      target = math.floor(tonumber(target) or -1)
      local liveVersion = math.floor(tonumber(mod.save:get(SAVE_SCHEMA_KEY, 0)) or 0)
      if target ~= fromVersion + 1 then
          return false, "non_sequential_schema_target"
      end
      if liveVersion ~= fromVersion then
          return false, "schema_base_changed:" .. tostring(liveVersion)
      end
      if type(mod.save:get(upgrade.transactionKey, nil)) == "table" then
          return false, "pending_schema_transaction"
      end
      local shadow = upgrade.newShadowStore(mod.save)
      local ok, result = pcall(migrate, shadow)
      if not ok then return false, tostring(result) end
      if result == false then
          return false, "schema migration v" .. tostring(target) .. " declined"
      end
      shadow:set(SAVE_SCHEMA_KEY, target)
      shadow:set(SAVE_MIGRATION_KEY, "v" .. tostring(target))
      local writes = shadow:changes()
      local txn = {
          api = 1, state = "applying", build = mod.exports.__beta26.build,
          from_schema = fromVersion, target_schema = target, writes = writes,
      }
      local wroteTxn, txnResult = pcall(mod.save.set, mod.save,
          upgrade.transactionKey, txn)
      if not wroteTxn or txnResult == false then
          return false, "could not persist migration transaction"
      end

      local applied = {}
      for _, row in ipairs(writes) do
          local writeOk, writeResult = pcall(mod.save.set, mod.save, row.key,
              row.after_present and row.after_value or nil)
          if not writeOk or writeResult == false then
              local rollbackOk = true
              -- Restore the failing row too: a setter that throws after mutating
              -- must not escape rollback merely because it never reached applied.
              local currentOk, currentResult = pcall(mod.save.set, mod.save, row.key,
                  row.before_present and row.before_value or nil)
              if not currentOk or currentResult == false then rollbackOk = false end
              for i = #applied, 1, -1 do
                  local old = applied[i]
                  local rok, rresult = pcall(mod.save.set, mod.save, old.key,
                      old.before_present and old.before_value or nil)
                  if not rok or rresult == false then rollbackOk = false end
              end
              if rollbackOk then
                  local clearOk, clearResult = pcall(mod.save.set, mod.save,
                      upgrade.transactionKey, nil)
                  rollbackOk = clearOk and clearResult ~= false
              end
              return false, "migration write failed for " .. tostring(row.key)
                  .. (rollbackOk and " (rolled back)" or " (recovery required)")
          end
          applied[#applied + 1] = row
      end
      mod.save:set(upgrade.transactionKey, nil)
      return true, { target_schema=target, write_count=#writes }
  end

  mod.exports.__beta26.saveUpgrade.status = function()
      local upgrade = mod.exports.__beta26.saveUpgrade
      local txn = mod.save:get(upgrade.transactionKey, nil)
      local rawSchema = mod.save:get(SAVE_SCHEMA_KEY, nil)
      return {
          status_api = 1,
          save_schema = tonumber(rawSchema) and math.floor(tonumber(rawSchema)) or 0,
          current_schema = CURRENT_SAVE_SCHEMA,
          last_migration = mod.save:get(SAVE_MIGRATION_KEY, nil),
          pending_transaction = type(txn) == "table",
          transaction_target = type(txn) == "table" and txn.target_schema or nil,
          transaction_write_count = type(txn) == "table"
              and type(txn.writes) == "table" and #txn.writes or 0,
          schema_supported = mod.exports.__beta26.saveSchemaSupported(),
          write_pause_reason = mod.exports.__beta26.saveWritePauseReason(),
          last_pipeline = compatPublicCopy(upgrade.lastRun),
          last_backup = compatPublicCopy(upgrade.lastBackup),
      }
  end

  -- 2.6.20: NEW GAME uses save.created rather than save.loaded on both
  -- generations. A fresh namespace is current-format by definition, so stamp
  -- Save Schema immediately instead of waiting for the first CONTINUE. This
  -- also clears save-scoped safe-stop state inherited from an abandoned/newer
  -- save before any writes target the newly adopted save bucket.
  mod.exports.__beta26.saveUpgrade.initializeFreshSave = function()
      saveSchemaTooNew = false
      saveMigrationError = nil
      mod.exports.__beta26.newerSchemaWarningShown = false
      mod.exports.__beta26.saveMigrationWarningShown = false
      mod.exports.__beta26.resetSafeStopWrites()

      -- Fresh saves already use current semantics. Preserve the historical
      -- one-time markers, then stamp the required schema marker LAST so seeing
      -- schema 4 always means the fresh-save initialization writes preceded it.
      local okWhiteout, whiteoutResult = pcall(mod.save.set, mod.save,
          "whiteout_semantics_restored_2531", true)
      local okMovement, movementResult = pcall(mod.save.set, mod.save,
          "movement_assist_modes_2533", true)
      local okSchema, schemaResult = pcall(mod.save.set, mod.save,
          SAVE_SCHEMA_KEY, CURRENT_SAVE_SCHEMA)
      local schema = tonumber(mod.save:get(SAVE_SCHEMA_KEY, nil))
      local ok = okWhiteout and whiteoutResult ~= false
          and okMovement and movementResult ~= false
          and okSchema and schemaResult ~= false
          and schema ~= nil and math.floor(schema) == CURRENT_SAVE_SCHEMA
      if not ok then
          saveMigrationError = "fresh_save_schema_initialization_failed"
          return false, saveMigrationError
      end
      return true
  end

  mod.exports.__beta26.saveUpgrade.audit = function()
      local errors = {}
      local upgrade = mod.exports.__beta26.saveUpgrade
      if type(upgrade.transactionKey) ~= "string"
          or upgrade.transactionKey:sub(1, 11) ~= "__nuzlocke_" then
          errors[#errors + 1] = "transaction_key_not_namespaced"
      end
      for version = 1, CURRENT_SAVE_SCHEMA do
          if type(upgrade.schemaMigrations[version]) ~= "function" then
              errors[#errors + 1] = "missing_schema_migration_v" .. tostring(version)
          end
      end
      if math.floor(tonumber(upgrade.backupDepth) or 0) ~= 3 then
          errors[#errors + 1] = "unexpected_backup_depth"
      end
      if type(upgrade.backupSuffix) ~= "string"
          or upgrade.backupSuffix:find("nuzlocke", 1, true) == nil then
          errors[#errors + 1] = "invalid_backup_suffix"
      end
      for _, name in ipairs({ "newShadowStore", "createPreMigrationBackup",
          "previewPendingSchemaMigrations", "recoverSchemaTransaction",
          "applySchemaMigration", "initializeFreshSave", "status" }) do
          if type(upgrade[name]) ~= "function" then
              errors[#errors + 1] = "missing_" .. name
          end
      end
      return { ok=#errors == 0, errors=errors, save_schema=CURRENT_SAVE_SCHEMA,
          transaction_api=1 }
  end

  H.runSaveMigrations = function()
      local rawVersion = mod.save:get(SAVE_SCHEMA_KEY, nil)
      local version = tonumber(rawVersion)
      if version == nil then version = 0 end
      version = math.floor(version)

      if version > CURRENT_SAVE_SCHEMA then
          -- A downgraded mod must not reconstruct or reproject state written by
          -- a schema it does not understand. The coordinator treats this as a
          -- safe stop rather than as corruption.
          saveSchemaTooNew = true
          saveMigrationError = nil
          return false, "newer_schema"
      end

      -- Snapshot the authoritative raw save before any numbered-schema
      -- recovery/transition mutation.  Rotation is bounded and separate from
      -- Gen1Recomp's own .bak/.tmp files.  Failure is recorded for diagnostics
      -- but does not strand an otherwise recoverable save.
      local pendingTxn = mod.save:get(
          mod.exports.__beta26.saveUpgrade.transactionKey, nil)
      if version < CURRENT_SAVE_SCHEMA or type(pendingTxn) == "table" then
          mod.exports.__beta26.saveUpgrade.createPreMigrationBackup(
              currentGame, currentSave)
      end

      -- A prior failed attempt may have paused the central writer in this same
      -- process. Clear only the transient error before recovery so the durable
      -- journal can restore/finish its own transition; any new failure is
      -- recorded again by the coordinator immediately.
      saveMigrationError = nil

      -- 2.6.57: recover an interrupted gameplay mutation before schema
      -- transitions or normal enforcement resumes. Unknown/newer transaction
      -- kinds fail closed into the existing migration-error persistence pause;
      -- never guess whether a partially performed mutation should be replayed.
      local gameplayRecovered, gameplayDetail =
          mod.exports.__beta26.GameplayTransactions.recover()
      if not gameplayRecovered then
          error("gameplay transaction recovery failed: " .. tostring(gameplayDetail))
      end

      -- 2.5.78: resolve an interrupted schema transaction before attempting
      -- another transition. A journal from a newer schema is itself a safe-stop
      -- condition because this build cannot know that transaction's semantics.
      local recovered, recoveryDetail =
          mod.exports.__beta26.saveUpgrade.recoverSchemaTransaction(version)
      if not recovered then
          if recoveryDetail == "newer_transaction" then
              saveSchemaTooNew = true
              saveMigrationError = nil
              return false, "newer_schema"
          end
          error("schema transaction recovery failed: " .. tostring(recoveryDetail))
      end
      rawVersion = mod.save:get(SAVE_SCHEMA_KEY, nil)
      version = math.floor(tonumber(rawVersion) or 0)

      saveSchemaTooNew = false
      saveMigrationError = nil
      while version < CURRENT_SAVE_SCHEMA do
          local target = version + 1
          local migrate = mod.exports.__beta26.saveUpgrade.schemaMigrations[target]
          if type(migrate) ~= "function" then
              error("missing schema migration v" .. tostring(target))
          end
          local applied, detail =
              mod.exports.__beta26.saveUpgrade.applySchemaMigration(
                  version, target, migrate)
          if not applied then
              error("schema migration v" .. tostring(target) .. " failed: "
                  .. tostring(detail))
          end
          version = target
      end
      return true
  end

  mod.exports.__beta26.registerSaveUpgradeStep("schema", "numbered_schema", function()
      return H.runSaveMigrations()
  end)

  -- Semantic migrations are version-independent corrections with their own
  -- durable markers. Keeping them in the same ordered plan prevents a future
  -- one-off from becoming an invisible save.loaded side path.
  mod.exports.__beta26.registerSaveUpgradeStep("semantic",
      "retired_ball_ban_no_catching", function()
          local legacyBallTier = tonumber(mod.save:get("ball_use_ban_tier", 0)) or 0
          if mod.save:get("no_catching_migrated_2934", false) ~= true then
              if mod.save:get("no_catching", nil) == nil then
                  mod.save:set("no_catching", false)
              end
              mod.save:set("no_catching_migrated_2934", true)
          elseif mod.save:get("no_catching_migration_reviewed_29313", false) ~= true then
              -- 29.3.4-29.3.12 may have enabled No Catching from a partial Ball
              -- tier, but the player may also have enabled it intentionally.
              -- Never rewrite ambiguous intent; surface the existing review flag.
              local ambiguous = legacyBallTier > 0
                  and mod.save:get("no_catching", false) == true
              mod.save:set("no_catching_legacy_ambiguous_29313", ambiguous or nil)
              mod.save:set("no_catching_migration_reviewed_29313", true)
          end
          return true
      end)

  -- 2.5.31 restores the original public meaning of Whiteout: ON is the
  -- survivable branch, OFF is destructive Blackout. 2.5.30 and its ancestors
  -- used the inverse boolean internally, so invert an existing save exactly
  -- once to preserve the behavior the player had selected. Missing old values
  -- are old-default OFF and therefore become the new survivable ON.
  mod.exports.__beta26.registerSaveUpgradeStep("semantic",
      "whiteout_semantics_restored_2531", function()
          if mod.save:get("whiteout_semantics_restored_2531", false) ~= true then
              local oldValue = mod.save:get("whiteout_clause", nil)
              if type(oldValue) ~= "boolean" then oldValue = false end
              mod.save:set("whiteout_clause", not oldValue)
              mod.save:set("whiteout_semantics_restored_2531", true)
          end
          return true
      end)

  -- 2.5.33 turns the historical Running Shoes boolean into a three-state
  -- movement-assist mode: OFF / HOLD B / ALWAYS. Preserve the old ON meaning
  -- exactly as HOLD B, and seed the new Fast Surf control OFF. The defensive
  -- readers below still accept legacy booleans for imported/hand-edited saves.
  mod.exports.__beta26.registerSaveUpgradeStep("semantic",
      "movement_assist_modes_2533", function()
          if mod.save:get("movement_assist_modes_2533", false) ~= true then
              local running = mod.save:get("automatic_running_shoes", nil)
              if type(running) == "boolean" then
                  mod.save:set("automatic_running_shoes", running and 1 or 0)
              elseif running ~= nil then
                  mod.save:set("automatic_running_shoes",
                      math.max(0, math.min(2, math.floor(tonumber(running) or 0))))
              end
              local surf = mod.save:get("fast_surf", nil)
              if type(surf) == "boolean" then
                  mod.save:set("fast_surf", surf and 1 or 0)
              elseif surf == nil then
                  mod.save:set("fast_surf", 0)
              else
                  mod.save:set("fast_surf",
                      math.max(0, math.min(2, math.floor(tonumber(surf) or 0))))
              end
              mod.save:set("movement_assist_modes_2533", true)
          end
          return true
      end)

  -- 2.7.93 merges Running Shoes and Fast Surf into one Run / Surf row.
  -- Existing saves choose the MORE RESTRICTIVE historical mode when the two
  -- disagree, so updating never enables an assist the player had disabled.
  -- The old keys remain synchronized compatibility mirrors only.
  mod.exports.__beta26.registerSaveUpgradeStep("semantic",
      "run_surf_merged_2793", function()
          if mod.save:get("run_surf_merged_2793", false) ~= true then
              local function legacyMovementMode(value)
                  if type(value) == "boolean" then return value and 1 or 0 end
                  return math.max(0, math.min(2,
                      math.floor(tonumber(value) or 0)))
              end
              local existing = mod.save:get("run_surf", nil)
              local mode
              if existing ~= nil then
                  mode = legacyMovementMode(existing)
              else
                  mode = math.min(
                      legacyMovementMode(mod.save:get("automatic_running_shoes", 0)),
                      legacyMovementMode(mod.save:get("fast_surf", 0)))
              end
              mod.save:set("run_surf", mode)
              mod.save:set("automatic_running_shoes", mode)
              mod.save:set("fast_surf", mode)
              mod.save:set("run_surf_merged_2793", true)
          end
          return true
      end)

  mod.exports.__beta26.runSaveUpgradePipeline = function(ev)
      local upgrade = mod.exports.__beta26.saveUpgrade
      local save = type(ev) == "table" and ev.save or nil
      local game = type(ev) == "table" and ev.game or nil
      currentGame = game or currentGame
      currentSave = save or currentSave
      if currentGame and save then currentGame.save = save end

      local report = { ok = true, completed = {}, failed = nil }
      upgrade.lastRun = report
      for _, phase in ipairs(upgrade.phaseOrder) do
          local bucket = upgrade.steps[phase] or {}
          for _, step in ipairs(bucket) do
              local ok, result, detail = mod.exports.__beta26.Dev.pguard(
                  "save_upgrade:" .. tostring(phase) .. "/" .. tostring(step.id),
                  step.run, {
                      phase = phase, id = step.id, save = save or currentSave,
                      game = currentGame,
                  })
              if not ok then
                  report.ok = false
                  report.failed = { phase = phase, id = step.id,
                      error = tostring(result) }
                  saveMigrationError = phase .. "/" .. step.id .. ": " .. tostring(result)
                  return false
              end
              if result == false then
                  if phase == "schema" and detail == "newer_schema" then
                      report.ok = true
                      report.stopped = "newer_schema"
                      return false
                  end
                  report.ok = false
                  report.failed = { phase = phase, id = step.id,
                      error = tostring(detail or "step returned false") }
                  saveMigrationError = phase .. "/" .. step.id .. ": "
                      .. tostring(detail or "step returned false")
                  return false
              end
              report.completed[#report.completed + 1] = phase .. "/" .. step.id
          end
      end
      saveMigrationError = nil
      return true
  end

  -- This is intentionally the first save.loaded listener in the file. Every
  -- later migration-like task registers into the plan during module load, so
  -- by the time a save is emitted the coordinator can execute the complete
  -- deterministic pipeline before ordinary rule/UI listeners run.
  mod.events:on("save.loaded", function(ev)
      mod.exports.__beta26.runSaveUpgradePipeline(ev)
  end)

  -- A failed migration is a persistence-safety pause just like a future schema,
  -- but it has a distinct reason and recovery path.  Warn once per loaded
  -- session after the coordinator has had its chance to recover/retry.
  mod.events:on("save.loaded", function(ev)
      if saveMigrationError == nil then
          mod.exports.__beta26.saveMigrationWarningShown = false
          return
      end
      if mod.exports.__beta26.saveMigrationWarningShown == true then return end
      local game = type(ev) == "table" and ev.game or nil
      game = game or currentGame or mod.game
      if game and mod.exports.__beta26.pushWorldText then
          local ok, shown = pcall(mod.exports.__beta26.pushWorldText, game,
              "NUZLOCKE PAUSED\nA save migration could not complete safely. "
              .. "Nuzlocke writes and rule enforcement are paused to protect this save.")
          if ok and shown ~= false then
              mod.exports.__beta26.saveMigrationWarningShown = true
          end
      end
  end)

  -- NEW GAME is a save.created-only lifecycle on both generations; it does
  -- not pass through save.loaded. Initialize the fresh current-format save
  -- here so downgrade safety exists before the player's first save/reload.
  mod.events:on("save.created", function()
      mod.exports.__beta26.saveUpgrade.initializeFreshSave()
  end)

  mod.events:on("game.ready", function(ev)
      local game = type(ev) == "table" and ev.game or ev
      currentGame = game or currentGame
      currentSave = (game and game.save) or currentSave
      -- A newer save schema is deliberately read-only to this older build.
      if saveSchemaTooNew then
          -- Session-only warning: never persist acknowledgement into a schema
          -- this build has explicitly refused to write.
          if mod.exports.__beta26.newerSchemaWarningShown ~= true
              and game and mod.exports.__beta26.pushWorldText then
              local ok, shown = pcall(mod.exports.__beta26.pushWorldText, game,
                  "NUZLOCKE PAUSED\nThis save was written by a newer Nuzlocke build. "
                  .. "Rule enforcement and save repairs are disabled to protect it.")
              if ok and shown ~= false then
                  mod.exports.__beta26.newerSchemaWarningShown = true
              end
          end
          return
      end
      mod.exports.__beta26.newerSchemaWarningShown = false
      -- Wonderlocke is WIP and cannot be enabled in this beta.
      if mod.exports.__beta26.wonderlockeWip
          and mod.save:get("wonderlocke", false) ~= false then
          mod.save:set("wonderlocke", false)
      end
  end)

  ---------------------------------------------------------------------
  -- INTER-MOD COMPATIBILITY / PROVIDER REGISTRY
  -- Capability-based only; never match mod names/descriptions.
  -- Providers are discovered from active loaded mods and revalidated with
  -- mod.find() at point of use, so disabled/failed mods do not interfere.
  -- Supported capabilities: level_caps, postgame_caps, escape, encounters, npc_talk,
  -- npc_behavior, npc_visibility, npc_movement. NPC capabilities are optional
  -- ownership declarations; vanilla NPC behavior remains ours unless another
  -- mod explicitly exports a provider.
  ---------------------------------------------------------------------
  local COMPAT_PROVIDERS = {
      level_caps = nil, postgame_caps = nil, escape = nil, encounters = nil,
      npc_talk = nil, npc_behavior = nil, npc_visibility = nil, npc_movement = nil,
      wonder_trade = nil, pokemon_identity = nil, species_metadata = nil,
      battle_stats = nil, stat_growth = nil, identity_dvs = nil,
      move_category_model = nil, species_evolutions = nil,
  }
  -- 2.7.64: retain every live provider candidate, not only the first one.
  -- MOD COMPAT can then pin a capability to AUTO, Nuzlocke/Engine, or a
  -- specific installed provider without inventing ownership that the provider
  -- did not actually advertise. Preferences are save-local and fail open.
  local COMPAT_PROVIDER_CANDIDATES = {}

  local function compatOwnerPreference(capability)
      local prefs = mod.save:get("compat_owner_preferences", {})
      local value = type(prefs) == "table" and prefs[tostring(capability)] or nil
      value = tostring(value or "auto")
      return value ~= "" and value or "auto"
  end

  local function setCompatOwnerPreference(capability, value)
      capability = tostring(capability or "")
      if capability == "" then return false end
      local current = mod.save:get("compat_owner_preferences", {})
      local prefs = {}
      for k, v in pairs(type(current) == "table" and current or {}) do prefs[k] = v end
      value = tostring(value or "auto")
      if value == "auto" then prefs[capability] = nil else prefs[capability] = value end
      mod.save:set("compat_owner_preferences", prefs)
      return true
  end
  local COMPAT_CAPABILITIES = {
      "level_caps", "postgame_caps", "escape", "encounters",
      "npc_talk", "npc_behavior", "npc_visibility", "npc_movement", "wonder_trade",
      "pokemon_identity", "species_metadata",
      -- beta.27.3: compatibility negotiation also advertises the shared engine
      -- surfaces most likely to be wrapped by other gameplay/UI mods. These are
      -- metadata/handshake capabilities; merely discovering one does not give a
      -- third-party mod ownership of Nuzlocke policy.
      "item_use", "shopping", "healing", "battle_finish", "trainer_card", "party_menu",
      "start_menu_items", "screens", "static_encounters", "gambling",
      "encounter_area_projection", "trainer_party", "boss_level_caps",
      "battle_classification", "movement_speed", "starter_randomization",
      -- 2.4.34 internal mechanics dimensions. These are still private
      -- compatibility signals; exposing a stable third-party registration
      -- contract is intentionally deferred until the model has runtime proof.
      "battle_stats", "stat_growth", "identity_dvs",
      "move_category_model", "species_evolutions",
      -- 2.7.65: optional mechanic-presence contracts. These do not grant
      -- challenge-policy ownership; they only make otherwise N/A rules eligible.
      "overworld_encounters", "safari_zone", "gym_guide_rare_candy", "starter_trio", "pokegear_radio", "cherrygrove_tour",
  }

