          end
          return warnings
      end,
      getTypeLockAllowedTypes = function()
          local out = {}
          for i, value in ipairs(mod.exports.__beta26.typeLockAllowedTypes()) do
              out[i] = value
          end
          return out
      end,
      typeLockAllowsSpecies = function(game, species)
