  -- presentation can require real runtime evidence before exposing a Kanto
  -- seed row, while dynamically discovered Johto/custom areas remain eligible.
  local GEN1_SEED_IDS = {}
  for id in pairs(ROUTE_ORDER) do GEN1_SEED_IDS[id] = true end

