  local function providerDisplay(provider)
      if type(provider) ~= "table" then return nil end
      local id = provider.id
      local name = provider.name or provider.display_name or provider.displayName
      local version = provider.version
      if id and (not name or name == id) then
          local ok, other = pcall(mod.find, id)
          if ok and other then
              name = other.name or (other.manifest and other.manifest.name) or name or id
              version = version or other.version
          end
      end
      return {
          id = id or name or "external",
          name = name or id or "External Mod",
          version = version,
      }
  end

  -- beta.30.1.20: PokemonRecompRandomizer exposes a stable read-only
  -- contractVersion=1 active-run API rather than Nuzlocke's generic provider
  -- capability names. Adapt only the mechanics its CURRENT Gen1 run actually
  -- owns. Merely installing/enabling the companion never disables our controls.
  mod.exports.__beta26.pokemonRandomizerOwnership = function(key, game)
      if mod.exports.__beta26.runtimeIsGen2(game or currentGame or mod.game) then
          return nil
      end
      local okFind, provider = pcall(mod.find, "pokemon_randomizer")
      if not okFind or type(provider) ~= "table" then return nil end
      local exports = provider.exports
      if type(exports) ~= "table" or tonumber(exports.contractVersion) ~= 1
          or type(exports.save) ~= "table"
          or type(exports.save.activeRun) ~= "function" then
          return nil
      end
      local okRun, run = pcall(exports.save.activeRun)
      if not okRun or type(run) ~= "table"
          or type(run.settings) ~= "table" then return nil end
      local settings = run.settings
      local owns = false
      if key == "random_starter" then
          owns = settings.starters ~= nil and settings.starters ~= "off"
      elseif key == "random_encounter_tables" then
          -- Fishing is a separate runtime seam in PokemonRecompRandomizer; a
          -- fishing-only run therefore does not claim our encounter-table pass.
          owns = settings.wild_pokemon ~= nil and settings.wild_pokemon ~= "off"
      elseif key == "random_learnsets" or key == "random_learnset_generation" or key == "random_learnset_stab" then
          owns = (settings.pokemon_movesets ~= nil
                  and settings.pokemon_movesets ~= "vanilla")
              or (settings.learnset_levels ~= nil
                  and settings.learnset_levels ~= "vanilla")
      end
      if not owns then return nil end
      return {
          id = "pokemon_randomizer",
          name = provider.name or (provider.manifest and provider.manifest.name)
              or "Pokemon Gen 1 Randomizer",
          version = provider.version or (provider.manifest and provider.manifest.version),
          capability = (NON_CORE_DELEGATION[key] and NON_CORE_DELEGATION[key].label)
              or key,
          relationship = "public_api",
          activeRun = true,
      }
  end


  -- 2.2.14: Gen 2 Randomizer+ currently exposes only `isInstalled()`, not the
  -- generic Nuzlocke provider contract. Its source does, however, persist its
  -- live toggles in the engine-owned modOptions bucket. Adapt only the three
  -- overlapping mechanics whose key names are source-confirmed. Installing the
  -- companion alone never delegates anything; the individual Randomizer+
  -- option must actually be ON.
  mod.exports.__beta26.gen2RandomizerPlusOwnership = function(key, game)
      game = game or currentGame or mod.game
      if not mod.exports.__beta26.runtimeIsGen2(game) then return nil end

      local okFind, provider = pcall(mod.find, "gen_2_randomizer_plus")
      if not okFind or type(provider) ~= "table" then return nil end
      local exports = provider.exports
      if type(exports) == "table" and type(exports.isInstalled) == "function" then
          local okInstalled, installed = pcall(exports.isInstalled)
          if not okInstalled or installed ~= true then return nil end
      end

      local loader = game and game.mods
      local buckets = loader and loader.modOptions
      local settings = type(buckets) == "table"
          and buckets["gen_2_randomizer_plus"] or nil
      if type(settings) ~= "table" then return nil end

      local owns = false
      if key == "random_starter" then
          owns = settings.randomStarters == true
      elseif key == "random_encounter_tables" then
          owns = settings.randomWildPokemon == true
      elseif key == "random_learnsets"
          or key == "random_learnset_generation" or key == "random_learnset_stab" then
          owns = settings.randomMoveLearnset == true
      end
      if not owns then return nil end

      return {
          id = "gen_2_randomizer_plus",
          name = provider.name
              or (provider.manifest and provider.manifest.name)
              or "Gen 2 Randomizer+",
          version = provider.version
              or (provider.manifest and provider.manifest.version),
          capability = (NON_CORE_DELEGATION[key] and NON_CORE_DELEGATION[key].label)
              or key,
          relationship = "source_confirmed_settings",
          activeRun = true,
      }
  end

  -- 2.6.90: Item Randomizer exposes a stable mod id and source-confirmed
  -- per-generation option keys. Delegate only the visible pickup mechanic that
  -- overlaps Nuzlocke Random Field Items; hidden finds, shops, gifts, berries,
  -- held items, and PC rewards remain composition-only and do not disable us.
  mod.exports.__beta26.itemRandomizerOwnership = function(key, game)
      if key ~= "random_field_items"
          and key ~= "random_field_item_balance"
          and key ~= "random_field_item_repetition" then
          return nil
      end
      game = game or currentGame or mod.game
      local okFind, provider = pcall(mod.find, "item_randomizer")
      if not okFind or type(provider) ~= "table" then return nil end

      local function optionValue(optionKey)
          local options = provider.options
          if options and type(options.get) == "function" then
              local ok, value = pcall(options.get, options, optionKey)
              if ok and value ~= nil then return value end
          end
          local loader = game and game.mods
          local buckets = loader and loader.modOptions
          local settings = type(buckets) == "table"
              and buckets["item_randomizer"] or nil
          if type(settings) == "table" and settings[optionKey] ~= nil then
              return settings[optionKey]
          end
          return nil
      end

      local gen2 = mod.exports.__beta26.runtimeIsGen2(game)
      local optionKey = gen2 and "gold_ball_items" or "overworld_items"
      if optionValue(optionKey) ~= true then return nil end

      return {
          id = "item_randomizer",
          name = provider.name
              or (provider.manifest and provider.manifest.name)
              or "Item Randomizer",
          version = provider.version
              or (provider.manifest and provider.manifest.version),
          capability = "visible field-item randomization",
          relationship = "source_confirmed_settings",
          activeRun = true,
          option = optionKey,
      }
  end

  -- 2.5.33: QoL Toggles' source-confirmed run_hold_b overlaps only the
  -- HOLD-B behavior, not our new ALWAYS mode. Keep detecting it as composition
  -- metadata, but do not delegate/disable the Nuzlocke three-state control.
  mod.exports.__beta26.qolToggleValue = function(key, game)
      local okFind, provider = pcall(mod.find, "qol_toggles")
      if not okFind or type(provider) ~= "table" then return nil end
      if provider.options and type(provider.options.get) == "function" then
          local ok, value = pcall(provider.options.get, provider.options, key)
          if ok and value ~= nil then return value end
      end
      game = game or currentGame or mod.game
      local loader = game and game.mods
      local buckets = loader and loader.modOptions
      local settings = type(buckets) == "table" and buckets["qol_toggles"] or nil
      if type(settings) == "table" and settings[key] ~= nil then
          return settings[key]
      end
      local exports = provider.exports
      if type(exports) == "table" and type(exports.defaultFor) == "function" then
          local ok, value = pcall(exports.defaultFor, key)
          if ok then return value end
      end
      return nil
  end

  mod.exports.__beta26.qolTogglesOwnership = function(key, game)
      if key ~= "run_surf"
          or mod.exports.__beta26.qolToggleValue("run_hold_b", game) ~= true then
          return nil
      end
      local okFind, provider = pcall(mod.find, "qol_toggles")
      if not okFind or type(provider) ~= "table" then return nil end
      return {
          id = "qol_toggles",
          name = provider.name or (provider.manifest and provider.manifest.name)
              or "QoL Toggles",
          version = provider.version or (provider.manifest and provider.manifest.version),
          capability = "running shoes",
          relationship = "source_confirmed_settings",
          activeRun = true,
      }
  end

  mod.exports.__beta26.gen9DexOwnership = function(key, game)
      if key ~= "player_start_stat_exp" and key ~= "wild_start_stat_exp"
          and key ~= "trainer_start_stat_exp" and key ~= "no_player_stat_exp_gain" then
          return nil
      end
      game = game or currentGame or mod.game
      if not mod.exports.__beta26.runtimeIsGen2(game) then return nil end
      local cap = mod.exports.__beta26.mechanicsCapability("stat_growth", game)
      if not (type(cap) == "table" and cap.supplied and cap.id == "g9-battle-engine") then return nil end
      return { id=cap.id, name=cap.name or "Gen 9 Battle Engine", version=cap.version,
          capability="modern EV/Nature battle-stat growth",
          relationship="external_modern_stats", nativeOnly=true }
  end

  mod.exports.__beta26.kantoReforgedEncounterOwnership = function(key, game)
      if key ~= "random_encounter_tables" then return nil end
      local okFind, provider = pcall(mod.find, "Kanto-Reforged")
      if not okFind or type(provider) ~= "table" then return nil end
      local options = provider.options
      if not (options and type(options.get) == "function") then return nil end
      local okHost, Host = pcall(require, "mods.Kanto-Reforged.core.host")
      if not okHost or type(Host) ~= "table" or type(Host.optionKey) ~= "function" then return nil end
      local function enabled(name)
          local okKey, optionKey = pcall(Host.optionKey, name)
          if not okKey or not optionKey then return false end
          local okGet, value = pcall(options.get, options, optionKey)
          return okGet and value == true
      end
      local pure = enabled("pure_spawn_random")
      local full = enabled("full_spawn_random")
      if not pure and not full then return nil end
      return {
          id = provider.id or "Kanto-Reforged",
          name = provider.name or (provider.manifest and provider.manifest.name) or "Kanto Reforged",
          version = provider.version or (provider.manifest and provider.manifest.version) or "1.3.0",
          capability = "encounter randomization",
          relationship = "exclusive",
          mode = pure and "PURE RANDOM SPAWN" or "FULL SPAWN MIX",
      }
  end

  externalRuleDelegation = function(key, game)
      local spec = NON_CORE_DELEGATION[key]
      if not spec then return nil end

      local adapted = mod.exports.__beta26.kantoReforgedEncounterOwnership(key, game)
      if adapted then return adapted end
      adapted = mod.exports.__beta26.gen9DexOwnership(key, game)
      if adapted then return adapted end
      adapted = mod.exports.__beta26.pokemonRandomizerOwnership(key, game)
      if adapted then return adapted end
      adapted = mod.exports.__beta26.gen2RandomizerPlusOwnership(key, game)
      if adapted then return adapted end
      adapted = mod.exports.__beta26.itemRandomizerOwnership(key, game)
      if adapted then return adapted end
      adapted = mod.exports.__beta26.qolTogglesOwnership(key, game)
      if adapted then return adapted end

      -- Older compatibility-provider contract. Only a provider whose declared
      -- relationship is delegate/exclusive owns our duplicate control.
      if spec.legacy then
          local provider = activeCompatProvider(spec.legacy, game)
          if provider then
              local relation = mod.exports.__beta26.compat.Mods.relationshipFor(
                  provider.id, spec.legacy)
              if relation == "delegate" or relation == "exclusive" then
                  local out = providerDisplay(provider) or {}
                  out.capability = spec.label or spec.legacy
                  out.relationship = relation
                  return out
              end
          end
      end

      -- Interop API v1 provider registry. Explicit providers win inside
      -- resolveCapability(); automatic adapters are only the fallback.
      local interop = mod.exports.nuzlocke and mod.exports.nuzlocke.interop
      if interop and type(interop.resolveCapability) == "function" then
          for _, capability in ipairs(spec.capabilities or {}) do
              local ok, result = pcall(interop.resolveCapability, capability)
              if ok and type(result) == "table" and result.supplied
                  and type(result.preferred) == "table" then
                  local out = providerDisplay(result.preferred) or {}
                  out.capability = spec.label or capability
                  out.relationship = result.preferred.automatic and "automatic" or "explicit"
                  return out
              end
          end
      end
      return nil
  end

  mod.exports.__beta26.randomizerCompatibilitySnapshot = function(game)
      game = game or currentGame or mod.game
      local rows = {}
      local checks = {
          { key="random_starter", label="starter" },
          { key="random_encounter_tables", label="encounters" },
          { key="random_field_items", label="field_items" },
          { key="random_learnsets", label="learnsets" },
          { key="random_trainers", label="trainers" },
          { key="random_evolutions", label="evolutions" },
          { key="random_shops", label="shops" },
          { key="random_tms", label="tms" },
          { key="random_gift_items", label="gift_items" },
      }
      for _, check in ipairs(checks) do
          local ok, owner = pcall(externalRuleDelegation, check.key, game)
          rows[#rows + 1] = {
              mechanic = check.label,
              key = check.key,
              delegated = ok and type(owner) == "table" or false,
              owner_id = ok and type(owner) == "table"
                  and tostring(owner.id or owner.name or "external") or nil,
              owner = ok and type(owner) == "table"
                  and tostring(owner.name or owner.id or "external") or nil,
              relationship = ok and type(owner) == "table"
                  and tostring(owner.relationship or "delegated") or nil,
              capability = ok and type(owner) == "table"
                  and tostring(owner.capability or check.label) or nil,
              error = not ok and tostring(owner) or nil,
          }
      end
      return {
          edition = tostring(mod.exports.__beta26.currentEditionId
              and mod.exports.__beta26.currentEditionId(game) or ""),
          rows = rows,
      }
  end

  mod.exports.__beta26.externalRuleDelegation = externalRuleDelegation
  mod.exports.__beta26.nonCoreDelegationRules = NON_CORE_DELEGATION

  -- QoL Toggles AUTO-REPEL consumes a Repel directly through its exported
  -- helper rather than ItemEffects.use. Wrap that public helper once the mod
  -- is loaded so No Repels cannot be bypassed by automatic consumption.
  mod.exports.__beta26.installQolTogglesGuards = function()
      local okFind, provider = pcall(mod.find, "qol_toggles")
      if not okFind or type(provider) ~= "table"
          or type(provider.exports) ~= "table" then
          return false, "not_applicable", "qol_toggles mod absent"
      end
      local exports = provider.exports
      if type(exports.applyAutoRepel) ~= "function" then
          return false, "pending", "qol_toggles auto-repel hook unavailable"
      end
      if exports.__nuzlockeAutoRepelGuardOwner == mod
          and exports.applyAutoRepel == exports.__nuzlockeAutoRepelGuardFunction then
          return true
      end
      if exports.applyAutoRepel == exports.__nuzlockeAutoRepelGuardFunction
          and type(exports.__nuzlockeAutoRepelGuardPrevious) == "function" then
          exports.applyAutoRepel = exports.__nuzlockeAutoRepelGuardPrevious
      end
      local previous = exports.applyAutoRepel
      local wrapper = function(save, ...)
          if mod.exports.__beta26.ruleActive(currentGame or mod.game, "no_repels") then
              return nil
          end
          return previous(save, ...)
      end
      exports.applyAutoRepel = wrapper
      exports.__nuzlockeAutoRepelGuardOwner = mod
      exports.__nuzlockeAutoRepelGuardPrevious = previous
      exports.__nuzlockeAutoRepelGuardFunction = wrapper
      return true
  end
  mod.events:on("mods.loaded", function() mod.exports.__beta26.attemptInstall("qol.external_toggle_guards", mod.exports.__beta26.installQolTogglesGuards) end)
  mod.events:on("game.ready", function() mod.exports.__beta26.attemptInstall("qol.external_toggle_guards", mod.exports.__beta26.installQolTogglesGuards) end)
  mod.events:on("save.loaded", function() mod.exports.__beta26.attemptInstall("qol.external_toggle_guards", mod.exports.__beta26.installQolTogglesGuards) end)

  -- 2.4.34: built-in Save Editor / external save-state hardening.
  -- Persistent Nuzlocke death state wins over externally restored party HP;
  -- externally over-cap parties are detected without destructive correction;
  -- EDITED provenance is presented as EXTERNAL/UNVERIFIED while retaining the
  -- existing persisted token; identity registry speciesAtRegistration remains
  -- the immutable historical species while currentSpecies follows live state.

  -- 2.4.32: Quality of Life 1.3.0 Easy Interactions compatibility.
  -- On Gen 1 its SELECT shortcut can invoke FLY/TELEPORT/DIG below the
  -- public fieldmove.eligibility hook. Do not wrap low-level teleport/fly
  -- engine methods because scripted/story transportation may share them.
  -- Instead, conservatively suppress only this mod's SELECT shortcut handler
  -- while a travel veto or Dungeon Lock-In is active; normal game input then
  -- proceeds and the player can use ordinary rule-aware paths. Gold's arm
  -- already delegates to FieldMoves.fromMenu/world:useFieldMove and needs no
  -- private adapter. Repel shortcuts remain on ItemEffects.use (Gen 1) or
  -- World:useRepel (Gold), both covered by existing No Repels enforcement.
  mod.exports.__beta26.installQualityOfLifeGuards = function()
      local okFind, provider = pcall(mod.find, "quality_of_life")
      if not okFind or type(provider) ~= "table" then
          return false, "not_applicable", "quality_of_life mod absent"
      end
      local okOw, OverworldController = pcall(require, "src.world.OverworldController")
      if not okOw or type(OverworldController) ~= "table" then
          return false, "pending", "OverworldController not loaded"
      end
      local handlers = rawget(OverworldController, "__qolSelectHandlers")
      if type(handlers) ~= "table" then
          return false, "pending", "quality_of_life handler table unavailable"
      end
      local previous = handlers["quality_of_life"]
      if type(previous) ~= "function" then
          return false, "pending", "quality_of_life SELECT handler unavailable"
      end
      if OverworldController.__nuzlockeQualityOfLifeGuardOwner == mod
          and handlers["quality_of_life"] == OverworldController.__nuzlockeQualityOfLifeGuardFunction then
          return true
      end
      local wrapper
      wrapper = function(ow, ...)
          local game = (ow and ow.game) or currentGame or mod.game
          if mod.save:get("nuzlocke_enabled", true) == true then
              local travel = math.max(0, math.min(2, math.floor(tonumber(
                  mod.save:get("travel_restrictions",
                      defaultRuleValue("travel_restrictions"))) or 0)))
              local locked = type(mod.exports.__beta26.dungeonLockActive) == "function"
                  and mod.exports.__beta26.dungeonLockActive(game)
              if locked or travel > 0 then
                  return false
              end
          end
          return previous(ow, ...)
      end
      handlers["quality_of_life"] = wrapper
      OverworldController.__nuzlockeQualityOfLifeGuardOwner = mod
      OverworldController.__nuzlockeQualityOfLifeGuardFunction = wrapper
      OverworldController.__nuzlockeQualityOfLifeGuardPrevious = previous
      return true
  end
  mod.events:on("mods.loaded", function() mod.exports.__beta26.attemptInstall("qol.travel_lock_guard", mod.exports.__beta26.installQualityOfLifeGuards) end)
  mod.events:on("game.ready", function() mod.exports.__beta26.attemptInstall("qol.travel_lock_guard", mod.exports.__beta26.installQualityOfLifeGuards) end)
  mod.events:on("save.loaded", function() mod.exports.__beta26.attemptInstall("qol.travel_lock_guard", mod.exports.__beta26.installQualityOfLifeGuards) end)

  mod.exports.__beta26.effectiveToggle = function(key, default)
      if externalRuleDelegation and externalRuleDelegation(key, currentGame or mod.game) then
          return false
      end
      return mod.save:get(key, default == true) == true
  end

  local function getConfigValue(key, preGame)
      if key == "rules_locked"
          and mod.exports.__beta26.permanentRuleSealWip then
          return false
      end
      if type(mod.exports.__beta26.ruleOperationalState) == "function" then
          local operational = mod.exports.__beta26.ruleOperationalState(
              key, preGame, currentGame or mod.game)
          if operational ~= true then
              local spec = mod.exports.__beta26.ruleDefinitionByKey
                  and mod.exports.__beta26.ruleDefinitionByKey[key]
              if spec and spec.numeric then
                  local neutral = spec.neutral
                  if neutral == nil then neutral = spec.min end
                  return tonumber(neutral) or 0
              end
              return false
          end
      end
      local delegated = externalRuleDelegation and externalRuleDelegation(
          key, currentGame or mod.game)
      if delegated then
          local spec = mod.exports.__beta26.ruleDefinitionByKey
              and mod.exports.__beta26.ruleDefinitionByKey[key]
          if spec and spec.numeric then
              local neutral = spec.neutral
              if neutral == nil then neutral = spec.min end
              return tonumber(neutral) or 0
          end
          return false
      end
      if preGame then
          if not pendingNewGameRules then
              pendingNewGameRules = makeDefaultPreGameRules()
          end
          if key == "difficulty_profile" then
              local storedId = pendingNewGameRules.difficulty_provider_id
              if type(storedId) == "string" and storedId ~= ""
                  and type(Difficulty) == "table"
                  and type(Difficulty.optionById) == "function" then
                  local _, idx = Difficulty.optionById(storedId)
                  -- A missing external provider is shown as VANILLA without
                  -- erasing the requested stable id. Re-enabling the provider
                  -- restores the intended selection automatically.
                  return idx ~= nil and idx or 0
              end
          end
          local value = pendingNewGameRules[key]
          if value == nil then value = defaultRuleValue(key) end
          local spec = mod.exports.__beta26.ruleDefinitionByKey
              and mod.exports.__beta26.ruleDefinitionByKey[key]
          if spec and spec.preGameReadCoerce == true then
              return mod.exports.__beta26.coerceRuleValue(key, value, "read")
          end
          return value
      end

      if key == "area_guide_enabled" then
          return H.routeListShowsAll()
      end

      if key == "locke_type" then
          return math.max(0, math.min(6,
              math.floor(tonumber(mod.save:get("locke_type",
                  defaultRuleValue("locke_type"))) or 0)))
      end

      -- Preserve the pre-Schema-4 level-cap migration path. Once a concrete
      -- value exists, ordinary clamping is registry-driven like every other
      -- numeric rule.
      if key == "level_cap_scope" then
          local rawScope = mod.save:get("level_cap_scope", nil)
          if rawScope == nil then return legacyLevelCapScope() end
          return mod.exports.__beta26.coerceRuleValue(key, rawScope, "read")
      end

      local stored = mod.save:get(key, defaultRuleValue(key))
      if key == "difficulty_profile" then
          if type(Difficulty) == "table" and type(Difficulty.indexForSelection) == "function" then
              return math.max(0, math.min(15, Difficulty.indexForSelection()))
          end
      end
      return mod.exports.__beta26.coerceRuleValue(key, stored, "read")
  end



  ---------------------------------------------------------------------
  -- 2.4.35 DEVELOPER DIAGNOSTICS MODE
  --
  -- Dev Mode is deliberately read-only with respect to challenge semantics.
  -- It never changes legality, RNG, encounters, battle decisions, or rule
  -- values. The only persistent setting is the toggle itself. Diagnostics are
  -- kept in a small in-memory ring and mirrored to mod.log so a crash report
  -- can include the last successful Nuzlocke lifecycle milestones.
  ---------------------------------------------------------------------
  mod.exports.__beta26.Dev = mod.exports.__beta26.Dev or {
      maxBreadcrumbs = 48,
      sequence = 0,
      breadcrumbs = {},
  }
  -- 2.7.81 reconstruction: engine-owned developer signal (Gen1Recomp 0.2.21+).
  -- This is diagnostic metadata only and never enables Nuzlocke Dev Mode.
  mod.exports.__beta26.Dev.engineDeveloper = mod.developer == true

  -- 2.6.59: actual direct-wrapper interposition/reload-policy harness.
  -- Uses an isolated fake method table; it never touches engine modules.
  mod.exports.__beta26.Dev.wrapperInterpositionHarness = function()
      local fake = {}
      local baseCalls, nuzCalls, externalCalls = 0, 0, 0
      fake.run = function(v) baseCalls = baseCalls + 1; return v + 1 end
      local key = "__nuzlockeHarnessSession2658"
      local okInstall = installOwnedMethodWrapper(fake, key, "run", function(previous)
          return function(v) nuzCalls = nuzCalls + 1; return previous(v) + 10 end
      end)
      local first = fake.run(1)
      local nuzWrapper = fake.run
      local external = function(v) externalCalls = externalCalls + 1; return nuzWrapper(v) + 100 end
      fake.run = external
      local okReinstall = installOwnedMethodWrapper(fake, key, "run", function(previous)
          return function(v) return previous(v) + 1000 end
      end)
      local preservedExternal = fake.run == external
      local second = fake.run(1)
      return {
          ok = okInstall == true and okReinstall == true and preservedExternal
              and first == 12 and second == 112
              and baseCalls == 2 and nuzCalls == 2 and externalCalls == 1,
          installed = okInstall == true, reentry = okReinstall == true,
          external_preserved = preservedExternal, first = first, second = second,
          base_calls = baseCalls, nuz_calls = nuzCalls, external_calls = externalCalls,
      }
  end


  -- 2.4.65/2.4.70: session-instance lifecycle counters. Diagnostic
  -- listeners resolve mod.exports.__beta26.Dev dynamically, so stacked callbacks
  -- that reach the same current export can reveal duplicate delivery after a
  -- reload. Pre-reload counter totals are not promised to persist. Payload
  -- identity is tracked weakly: if the same event table reaches the current
  -- callback surface more than once, the extra delivery is counted.
  mod.exports.__beta26.Dev.lifecycle = mod.exports.__beta26.Dev.lifecycle or {
      counts = {},
      duplicateCallbacks = 0,
      duplicateByEvent = {},
      seen = {},
  }

  mod.exports.__beta26.Dev.countLifecycle = function(kind, payload)
      if not mod.exports.__beta26.Dev.enabled() then return false end
      local dev = mod.exports.__beta26.Dev
      local life = dev.lifecycle
      if type(life) ~= "table" then
          life = { counts={}, duplicateCallbacks=0, duplicateByEvent={}, seen={} }
          dev.lifecycle = life
      end
      life.counts = type(life.counts) == "table" and life.counts or {}
      life.duplicateByEvent = type(life.duplicateByEvent) == "table"
          and life.duplicateByEvent or {}
      life.seen = type(life.seen) == "table" and life.seen or {}

      kind = tostring(kind or "event")
      life.counts[kind] = (tonumber(life.counts[kind]) or 0) + 1

      if type(payload) == "table" then
          local seen = life.seen[kind]
          if type(seen) ~= "table" then
              seen = setmetatable({}, { __mode = "k" })
              life.seen[kind] = seen
          end
          if seen[payload] == true then
              life.duplicateCallbacks =
                  (tonumber(life.duplicateCallbacks) or 0) + 1
              life.duplicateByEvent[kind] =
                  (tonumber(life.duplicateByEvent[kind]) or 0) + 1
              mod.exports.__beta26.Dev.push("lifecycle.duplicate",
                  kind .. " callback repeated for same payload",
                  type(payload) == "table" and payload.game
                      or currentGame or mod.game)
          else
              seen[payload] = true
          end
      end
      return true
  end

  mod.exports.__beta26.Dev.lifecycleReport = function()
      local life = mod.exports.__beta26.Dev.lifecycle or {}
      local counts, duplicates = {}, {}
      for key, value in pairs(life.counts or {}) do
          counts[tostring(key)] = tonumber(value) or 0
      end
      for key, value in pairs(life.duplicateByEvent or {}) do
          duplicates[tostring(key)] = tonumber(value) or 0
      end
      return {
          counts = counts,
          duplicate_callbacks = tonumber(life.duplicateCallbacks) or 0,
          duplicate_by_event = duplicates,
          battle_delta = (tonumber(counts["battle.started"]) or 0)
              - (tonumber(counts["battle.ended"]) or 0),
      }
  end

  mod.exports.__beta26.Dev.resetLifecycle = function()
      mod.exports.__beta26.Dev.lifecycle = {
          counts = {},
          duplicateCallbacks = 0,
          duplicateByEvent = {},
          seen = {},
      }
      return true
  end

  -- 2.5.46: use the same authoritative live-config reader as NUZ RULES.
  -- Gold can keep its START menu instance underneath the rules screen, so a
  -- direct save-only read was not sufficient for immediate menu visibility.
  mod.exports.__beta26.Dev.enabled = function()
      local ok, value = pcall(getConfigValue, "dev_mode", false)
      if ok then return value == true end
      return mod.save:get("dev_mode", false) == true
  end

  -- 2.5.67: generation drives shared mechanics, but diagnostics and UI must
  -- preserve the exact running edition. This is the canonical diagnostic
  -- identity used by breadcrumbs, snapshots, self-test/NZR codes and parity
  -- accounting so Red/Blue/Yellow and Gold/Silver never collapse together.
  mod.exports.__beta26.Dev.gameId = function(game)
      local version = getGameVersion and getGameVersion() or nil
      if version == nil and type(game) == "table" then
          version = game.version or game.gameVersion
              or (game.data and (game.data.version or game.data.gameVersion))
      end
      local id = tostring(version or ""):lower()
      if id == "red" or id == "blue" or id == "yellow"
          or id == "gold" or id == "silver" or id == "crystal" then
          return id
      end
      return mod.exports.__beta26.runtimeIsGen2(game or currentGame or mod.game)
          and "gold" or "red"
  end

  mod.exports.__beta26.Dev.gameLabel = function(game)
      local id = mod.exports.__beta26.Dev.gameId(game)
      if id == "crystal" then return "CRYSTAL ALPHA" end
      return string.upper(id)
  end

  -- 2.6.26: generation decides shared adapter ownership; edition remains an
  -- independent diagnostic dimension so Gold evidence never silently counts as
  -- Silver evidence (or vice versa). This is additive Diagnostics API 1 data.
  mod.exports.__beta26.Dev.editionContext = function(game)
      game = game or currentGame or mod.game
      local edition = mod.exports.__beta26.Dev.gameId(game)
      local gen2 = mod.exports.__beta26.runtimeIsGen2(game)
      return {
          edition = edition,
          label = edition == "crystal" and "CRYSTAL ALPHA" or string.upper(edition),
          support_stage = edition == "crystal" and "ALPHA" or "SUPPORTED",
          generation = gen2 and 2 or 1,
          engine_family = gen2 and "gen2" or "gen1",
          profile_scope = mod.exports.__beta26.profileScopeForGame(game),
      }
  end

  -- 2.5.80: Run History is isolated to reduce main.lua size while preserving
